// --- Apply AI-suggested file write ---
app.post('/api/ai/apply', (req, res) => {
  const { filePath, content } = req.body;
  if (!filePath || typeof content !== 'string') {
    return res.status(400).json({ error: 'filePath and content required' });
  }

  const resolved = path.resolve(filePath.replace(/^~/, HOME));
  const config = loadConfig();
  const allowedRoots = [
    CLAUDE_DIR,
    ...config.projectDirs.map(d => path.resolve(d.replace(/^~/, HOME))),
  ];
  const allowed = allowedRoots.some(root => resolved.startsWith(root));
  if (!allowed) return res.status(403).json({ error: 'Path outside allowed directories' });

  ensureDir(path.dirname(resolved));
  fs.writeFileSync(resolved, content);
  res.json({ ok: true });
});

// Claude AI chat — uses local `claude` CLI via stdin (no API key required)
const { spawn } = require('child_process');

app.post('/api/ai/chat', (req, res) => {
  res.setTimeout(0); // No timeout — allow complex long-running requests
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  // Use stdin to avoid OS argument length limits; -p without an argument reads from stdin
  const proc = spawn(claudePath, ['-p'], {
    env: childEnv,
  });

  let output = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => { output += data.toString(); });
  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  proc.on('close', (code) => {
    if (code !== 0) {
      return res.status(500).json({ error: errOutput.trim() || `claude exited with code ${code}` });
    }
    res.json({ content: output.trim() });
  });

  proc.on('error', (err) => {
    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
  });

  // Write prompt via stdin and close
  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();
});

// --- Agent Orchestration ---
function loadOrchestrations() {
  try {
    if (fs.existsSync(ORCHESTRATIONS_PATH)) return JSON.parse(fs.readFileSync(ORCHESTRATIONS_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveOrchestrations(list) {
  fs.writeFileSync(ORCHESTRATIONS_PATH, JSON.stringify(list, null, 2));
}

app.get('/api/orchestrations', (req, res) => {
  res.json(loadOrchestrations());
});

app.post('/api/orchestrations', (req, res) => {
  const { id, name, nodes, edges } = req.body;
  if (!name || !Array.isArray(nodes) || !Array.isArray(edges)) {
    return res.status(400).json({ error: 'name, nodes, edges required' });
  }
  const list = loadOrchestrations();
  const now = new Date().toISOString();
  const orcId = id || genId();
  const idx = list.findIndex(o => o.id === orcId);
  const orc = { id: orcId, name, nodes, edges, updatedAt: now, createdAt: now };
  if (idx >= 0) { orc.createdAt = list[idx].createdAt; list[idx] = orc; }
  else list.unshift(orc);
  saveOrchestrations(list);
  res.json({ id: orcId });
});

app.get('/api/orchestrations/:id', (req, res) => {
  const orc = loadOrchestrations().find(o => o.id === req.params.id);
  if (!orc) return res.status(404).json({ error: 'Not found' });
  res.json(orc);
});

app.delete('/api/orchestrations/:id', (req, res) => {
  saveOrchestrations(loadOrchestrations().filter(o => o.id !== req.params.id));
  res.json({ ok: true });
});

// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

function runClaudeSync(prompt) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', reject);
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

app.post('/api/orchestrations/run', async (req, res) => {
  res.setTimeout(0);
  const { nodes, edges, task } = req.body;
  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });

  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
  const order = topoSort(nodes, edges || []);

  // Build agent content map from files
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const agentContentMap = {};

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

  for (const p of projects) {
    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
  }

  const results = {};
  let lastOutput = task;

  // SSE for streaming progress
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  try {
    for (const nodeId of order) {
      const node = nodeMap[nodeId];
      if (!node) continue;

      const agentName = node.data?.agentName;
      const agentInstructions = agentName ? (agentContentMap[agentName] || '') : (node.data?.instructions || '');
      const nodeLabel = node.data?.label || agentName || nodeId;

      send({ type: 'start', nodeId, label: nodeLabel });

      // Build prompt for this agent
      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
      let context = '';
      if (incomingEdges.length > 0) {
        context = incomingEdges.map(e => {
          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
        }).join('\n\n');
      } else {
        context = `## Task:\n${task}`;
      }

      const prompt = agentInstructions
        ? `${agentInstructions}\n\n---\n\n${context}\n\nProvide your response:`
        : `${context}\n\nProvide your response:`;

      try {
        const output = await runClaudeSync(prompt);
        results[nodeId] = output;
        lastOutput = output;
        send({ type: 'done', nodeId, label: nodeLabel, output });
      } catch (err) {
        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
        break;
      }
    }
    send({ type: 'complete', finalOutput: lastOutput });
  } catch (err) {
    send({ type: 'error', nodeId: null, label: null, error: err.message });
  }

  res.end();
});

// Global settings
app.get('/api/global/settings', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'settings.json'));
  try {
    res.json(content ? JSON.parse(content) : {});
  } catch {
    res.json({});
  }
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);
  console.log('');
});

