// Global Settings
export const getGlobalSettings = () => request<Record<string, unknown>>('/global/settings')

// Projects
export const getProjects = () => request<Project[]>('/projects')

// Project CLAUDE.md
export const getProjectClaudeMd = (id: string) =>
