// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

function runClaudeSync(prompt) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', reject);
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

app.post('/api/orchestrations/run', async (req, res) => {
  res.setTimeout(0);
  const { nodes, edges, task } = req.body;
  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });

  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
  const order = topoSort(nodes, edges || []);

  // Build agent content map from files
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const agentContentMap = {};

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

  for (const p of projects) {
    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
  }

  const results = {};
  let lastOutput = task;

  // SSE for streaming progress
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  try {
    for (const nodeId of order) {
      const node = nodeMap[nodeId];
      if (!node) continue;

      const agentName = node.data?.agentName;
      const agentInstructions = agentName ? (agentContentMap[agentName] || '') : (node.data?.instructions || '');
      const nodeLabel = node.data?.label || agentName || nodeId;

      send({ type: 'start', nodeId, label: nodeLabel });

      // Build prompt for this agent
      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
      let context = '';
      if (incomingEdges.length > 0) {
        context = incomingEdges.map(e => {
          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
        }).join('\n\n');
      } else {
        context = `## Task:\n${task}`;
      }

      const prompt = agentInstructions
        ? `${agentInstructions}\n\n---\n\n${context}\n\nProvide your response:`
        : `${context}\n\nProvide your response:`;

      try {
        const output = await runClaudeSync(prompt);
        results[nodeId] = output;
        lastOutput = output;
        send({ type: 'done', nodeId, label: nodeLabel, output });
      } catch (err) {
        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
        break;
      }
    }
    send({ type: 'complete', finalOutput: lastOutput });
  } catch (err) {
    send({ type: 'error', nodeId: null, label: null, error: err.message });
  }

  res.end();
});

