                          <div className="border-t border-border p-4 bg-surface-2">
                            <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap leading-relaxed">
                              {cmd.content}
                            </pre>
                          </div>
                        )}
                      </div>
                    )
                  })}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  ShieldCheck,
  Search,
  FolderOpen,
  Clock,
  ChevronDown,
  ChevronRight,
  Plus,
  Trash2,
  Pencil,
  X,
} from 'lucide-react'
import { getUnifiedRules, deleteProjectRule, updateProjectRule, sanitizeName } from '../lib/api'
import { getProjects } from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedRule } from '../types'
import { toast } from '../components/Toast'

export default function AllRules() {
  const { data: rules, loading, refetch } = useApi(getUnifiedRules)
  const { data: projects } = useApi(getProjects)
  const navigate = useNavigate()
  const [search, setSearch] = useState('')
  const [expanded, setExpanded] = useState<string | null>(null)
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [creating, setCreating] = useState(false)
  const [createLoading, setCreateLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [createProject, setCreateProject] = useState<string>('')
  const [deletingKeys, setDeletingKeys] = useState<Set<string>>(new Set())

  const filtered = (rules || []).filter((r) => {
    if (search && !r.name.toLowerCase().includes(search.toLowerCase())) return false
    if (projectFilter !== 'all' && r.projectId !== projectFilter) return false
    return true
  })

  const groups = new Map<string, UnifiedRule[]>()
  for (const rule of filtered) {
    const key = rule.projectName
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key)!.push(rule)
  }

  const uniqueProjects = [
    ...new Map((rules || []).map((r) => [r.projectId, { id: r.projectId, name: r.projectName }])).values(),
  ]

  const allProjects = projects || []

  const handleCreate = async () => {
    if (!newName.trim() || !createProject) return
    const slug = sanitizeName(newName)
    if (!slug) {
      toast('error', 'Invalid name — use letters, numbers, or hyphens')
      return
    }
    setCreateLoading(true)
    try {
      const template = `Describe the rule Claude must follow in this project.`
      await updateProjectRule(createProject, slug, template)
      setCreating(false)
      setNewName('')
      navigate(`/projects/${createProject}/rules/${slug}`)
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create rule')
    } finally {
      setCreateLoading(false)
    }
  }

  const handleDelete = async (rule: UnifiedRule) => {
    if (!confirm(`Delete rule "${rule.name}" from ${rule.projectName}?`)) return
    const key = `${rule.projectId}-${rule.name}`
    setDeletingKeys((prev) => new Set(prev).add(key))
    try {
      await deleteProjectRule(rule.projectId, rule.name)
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete rule')
    } finally {
      setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
    }
  }

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <ShieldCheck className="w-6 h-6 text-green" />
            All Rules
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {rules?.length || 0} rules across all projects
          </p>
        </div>
        <button
          onClick={() => { setCreating(true); setCreateProject(allProjects[0]?.id || '') }}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Rule
        </button>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search rules..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>
        {uniqueProjects.length > 1 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
          >
            <option value="all">All projects</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        )}
      </div>

      {/* Create */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Rule</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="rule-name (e.g. no-console-log)"
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select
              value={createProject}
              onChange={(e) => setCreateProject(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              {allProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              disabled={!newName.trim() || !createProject || createLoading}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {createLoading ? 'Creating...' : 'Create'}
            </button>
          </div>
        </div>
      )}

      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <ShieldCheck className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No rules match your search' : 'No rules found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            Create rules to define constraints Claude must follow
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {[...groups.entries()].map(([projectName, projectRules]) => {
            const projectId = projectRules[0]?.projectId
            return (
              <div key={projectName}>
                <div className="flex items-center gap-2 mb-3">
                  <FolderOpen className="w-4 h-4 text-green" />
                  <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                    {projectName}
                  </h2>
                  <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                    {projectRules.length}
                  </span>
                </div>
                <div className="space-y-2">
                  {projectRules.map((rule) => {
                    const key = `${rule.projectId}-${rule.name}`
                    const isExpanded = expanded === key
                    return (
                      <div key={key} className="bg-surface border border-border rounded-xl overflow-hidden group">
                        <div className="flex items-center justify-between px-4 py-3">
                          <button
                            onClick={() => setExpanded(isExpanded ? null : key)}
                            className="flex items-center gap-3 flex-1 text-left"
                          >
                            <ShieldCheck className="w-4 h-4 text-green shrink-0" />
                            <span className="font-medium text-sm">{rule.name}</span>
                            {isExpanded ? (
                              <ChevronDown className="w-4 h-4 text-text-muted" />
                            ) : (
                              <ChevronRight className="w-4 h-4 text-text-muted" />
                            )}
                          </button>
                          <div className="flex items-center gap-2">
                            <span className="flex items-center gap-1 text-[11px] text-text-muted">
                              <Clock className="w-3 h-3" />
                              {new Date(rule.updatedAt).toLocaleDateString()}
                            </span>
                            <Link
                              to={`/projects/${projectId}/rules/${rule.name}`}
                              className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors opacity-0 group-hover:opacity-100"
                            >
                              <Pencil className="w-3.5 h-3.5" />
                            </Link>
                            <button
                              onClick={() => handleDelete(rule)}
                              disabled={deletingKeys.has(`${rule.projectId}-${rule.name}`)}
                              className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors opacity-0 group-hover:opacity-100"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        </div>
                        {isExpanded && (
                          <div className="border-t border-border p-4 bg-surface-2">
                            <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap leading-relaxed">
                              {rule.content}
                            </pre>
                          </div>
                        )}
                      </div>
                    )
                  })}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

