            </button>
          </div>
          <div className="flex gap-3">
            <select
              value={actionTarget}
              onChange={(e) => setActionTarget(e.target.value)}
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            >
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects
                .filter((p) => p.id !== actionAgent.projectId)
                .map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
            <button
              onClick={handleAction}
              disabled={!actionTarget || actioning}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {actioning ? 'Working...' : actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No agents match your search' : 'No agents found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            {search ? 'Try a different search term' : 'Create your first agent to get started'}
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global agents */}
          {globalAgents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-accent" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`global-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Per-project groups */}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {projectAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`${agent.projectId}-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}


function AgentRow({
  agent,
  deleting,
  onDelete,
  onCopy,
  onMove,
}: {
  agent: UnifiedAgent
  deleting: boolean
  onDelete: (a: UnifiedAgent) => void
  onCopy: (a: UnifiedAgent) => void
  onMove: (a: UnifiedAgent) => void
}) {
  const editLink =
    agent.scope === 'global'
      ? `/global/agents/${agent.filename}`
      : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-xl p-4 hover:border-accent/30 transition-all">
      <Link to={editLink} className="flex items-center gap-4 flex-1 min-w-0">
        <AgentAvatar name={agent.name} />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
              {agent.name}
            </h3>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-md font-medium ${
                agent.scope === 'global'
                  ? 'bg-accent-muted text-accent-hover'
                  : 'bg-amber-muted text-amber'
              }`}
            >
              {agent.scopeLabel}
            </span>
          </div>
          {agent.description && (
            <p className="text-xs text-text-secondary mt-0.5 truncate">{agent.description}</p>
          )}
          <div className="flex items-center gap-3 mt-1.5">
            {agent.model && (
              <span className="text-[11px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded font-mono">
                {agent.model}
              </span>
            )}
            <span className="flex items-center gap-1 text-[11px] text-text-muted">
              <Clock className="w-3 h-3" />
              {new Date(agent.updatedAt).toLocaleDateString()}
            </span>
          </div>
        </div>
      </Link>

      {/* Actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-3">
        <button
          onClick={(e) => { e.stopPropagation(); onCopy(agent) }}
          title="Copy to..."
          className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
        >
          <Copy className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onMove(agent) }}
          title="Move to..."
          className="p-1.5 rounded-md text-text-muted hover:text-amber hover:bg-amber-muted transition-colors"
        >
          <ArrowRightLeft className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(agent) }}
          title="Delete"
          disabled={deleting}
          className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

