const ICON_TYPES = [
  IconOrb, IconGem, IconNetwork, IconSpiral,
  IconLightning, IconWaves, IconEye, IconCompass,
]

interface AgentIconProps {
  name: string
  /** A unique key to namespace gradient IDs when the same name appears multiple times */
  uid?: string
  className?: string
  size?: number
  /** Use pixel-art character illustration (for global agents) */
  global?: boolean
}

/** Pixel-art character avatar via DiceBear API — used for global agents */
function PixelArtIcon({ name, size }: { name: string; size: number }) {
  const seed = encodeURIComponent(name.toLowerCase().replace(/[^a-z0-9-]/g, '-'))
  return (
    <div
      className="shrink-0 rounded-xl overflow-hidden bg-[#e8e8f8]"
      style={{ width: size, height: size }}
    >
